-- Catálogo inicial de ejercicios (HU-04)
-- url_multimedia apunta a una búsqueda de video de la técnica en YouTube
INSERT INTO ejercicio (nombre, grupo_muscular, equipo, tren, descripcion_tecnica, url_multimedia) VALUES
('Press de banca', 'Pecho', 'Barra', 'superior',
 'Acostado en el banco, pies apoyados y escápulas juntas. Baja la barra controlada hasta la parte media del pecho con los codos a unos 45 grados del torso y empuja hasta extender los brazos sin despegar la cadera.',
 'https://www.youtube.com/results?search_query=press+de+banca+tecnica+correcta'),
('Press inclinado con mancuernas', 'Pecho', 'Mancuernas', 'superior',
 'Banco a 30 o 45 grados. Baja las mancuernas a los lados del pecho con los antebrazos verticales y empuja hacia arriba juntándolas ligeramente al final, sin chocarlas.',
 'https://www.youtube.com/results?search_query=press+inclinado+mancuernas+tecnica'),
('Aperturas en máquina', 'Pecho', 'Máquina', 'superior',
 'Ajusta el asiento para que las manijas queden a la altura del pecho. Con los codos levemente flexionados, junta los brazos al frente y regresa despacio hasta sentir el estiramiento del pecho.',
 'https://www.youtube.com/results?search_query=aperturas+en+maquina+pec+deck+tecnica'),
('Fondos asistidos', 'Pecho', 'Máquina', 'superior',
 'Apoya las rodillas en la plataforma de asistencia. Baja inclinando el torso hacia adelante hasta que los codos formen unos 90 grados y empuja hasta extender los brazos.',
 'https://www.youtube.com/results?search_query=fondos+asistidos+maquina+tecnica'),
('Jalón al pecho', 'Espalda', 'Polea', 'superior',
 'Sentado con los muslos fijos bajo el soporte, toma la barra algo más ancho que los hombros. Lleva la barra hacia la parte alta del pecho bajando los codos y sin balancear el torso.',
 'https://www.youtube.com/results?search_query=jalon+al+pecho+tecnica+correcta'),
('Remo con barra', 'Espalda', 'Barra', 'superior',
 'Rodillas semiflexionadas y torso inclinado unos 45 grados con la espalda recta. Lleva la barra hacia el abdomen juntando las escápulas y bájala controlada.',
 'https://www.youtube.com/results?search_query=remo+con+barra+tecnica+correcta'),
('Remo sentado en polea', 'Espalda', 'Polea', 'superior',
 'Sentado con el pecho erguido y las rodillas levemente flexionadas. Tira del agarre hacia el abdomen manteniendo los codos pegados al cuerpo y regresa sin redondear la espalda.',
 'https://www.youtube.com/results?search_query=remo+sentado+polea+tecnica'),
('Sentadilla con barra', 'Piernas', 'Barra', 'inferior',
 'Barra sobre los trapecios, pies al ancho de los hombros. Baja llevando la cadera atrás y las rodillas en la dirección de los pies hasta que el muslo quede paralelo al suelo; sube empujando con todo el pie.',
 'https://www.youtube.com/results?search_query=sentadilla+con+barra+tecnica+correcta'),
('Prensa de piernas', 'Piernas', 'Máquina', 'inferior',
 'Espalda y cadera apoyadas en el respaldo, pies al ancho de los hombros en la plataforma. Baja hasta que las rodillas formen unos 90 grados y empuja sin bloquear las rodillas al final.',
 'https://www.youtube.com/results?search_query=prensa+de+piernas+tecnica+correcta'),
('Peso muerto rumano', 'Piernas', 'Barra', 'inferior',
 'De pie con la barra frente a los muslos y rodillas levemente flexionadas. Lleva la cadera atrás deslizando la barra por las piernas hasta media tibia con la espalda recta y vuelve apretando glúteos.',
 'https://www.youtube.com/results?search_query=peso+muerto+rumano+tecnica'),
('Extensión de cuádriceps', 'Piernas', 'Máquina', 'inferior',
 'Rodillas alineadas con el eje de la máquina y el rodillo sobre los tobillos. Extiende las piernas por completo, sostén un segundo y baja despacio.',
 'https://www.youtube.com/results?search_query=extension+de+cuadriceps+maquina+tecnica'),
('Press militar con mancuernas', 'Hombros', 'Mancuernas', 'superior',
 'Sentado con la espalda apoyada y las mancuernas a la altura de los hombros. Empuja hacia arriba sin arquear la zona lumbar y baja controlado hasta la altura de las orejas.',
 'https://www.youtube.com/results?search_query=press+militar+mancuernas+tecnica'),
('Elevaciones laterales', 'Hombros', 'Mancuernas', 'superior',
 'De pie con una leve flexión de codos. Eleva las mancuernas hacia los lados hasta la altura de los hombros, sin impulso del torso, y baja despacio.',
 'https://www.youtube.com/results?search_query=elevaciones+laterales+tecnica+correcta'),
('Curl de bíceps con barra', 'Brazos', 'Barra', 'superior',
 'De pie con los codos pegados al cuerpo. Flexiona los codos llevando la barra hacia los hombros sin balancear el torso y baja hasta extender los brazos.',
 'https://www.youtube.com/results?search_query=curl+de+biceps+con+barra+tecnica'),
('Extensión de tríceps en polea', 'Brazos', 'Polea', 'superior',
 'De pie frente a la polea alta con los codos fijos a los costados. Extiende los antebrazos hacia abajo hasta bloquear los codos y regresa sin despegar los brazos del cuerpo.',
 'https://www.youtube.com/results?search_query=extension+de+triceps+en+polea+tecnica'),
('Plancha abdominal', 'Core', 'Peso corporal', 'superior',
 'Apoyo sobre antebrazos y puntas de los pies con el cuerpo en línea recta. Contrae abdomen y glúteos y evita que la cadera caiga o se eleve. Registra los segundos sostenidos como repeticiones.',
 'https://www.youtube.com/results?search_query=plancha+abdominal+tecnica+correcta');
